\setstretch{1}
\caption{\small NOODL: Neurally plausible alternating Optimization-based Online Dictionary Learning.}\label{alg:main_alg}
\SetAlgoLined
\KwInput{Fresh data samples \[\b{y}_{(j)} \in \mathbb{R}^{n} \] for \[j \in [p]\] at each iteration \[t\] generated as per \eqref {eq:model}, where \[|\b{x}^*_i|\geq C\] for \[i \in {\rm supp}(\b{x}^*)\]. Parameters \[\eta_A\], \[\eta_x^{(r)}\] and \[\tau^{(r)}\] chosen as per \ref{assumption:step dict} and \ref{assumption:step coeff}. No. of iterations \[T = \Omega(\log(1/\epsilon_{T}))\] and \[R = \Omega(\log(1/\delta_{R}))\], for target tolerances \[\epsilon_{T}\] and \[\delta_{R}\].}
\KwOutput{The dictionary \[\b{A}^{(t)}\] and coefficient estimates \[\hat{\b{x}}_{(j)}^{(t)} \] for \[j \in [p]\] at each iterate \[t\]. }
\KwInit{Estimate \[\b{A}^{(0)}\], which is \[(\epsilon_0, 2)\]-near to \[\b{A}^*\] for \[\epsilon_0 = \mathcal{O}^*(1/\log(n))\]}
\For{\[t=0\] \textbf{to} \[T-1\]}{
\textbf{Predict: (Estimate Coefficients)}\\
\For{\[j = 1\] \textbf{to} \[p\]}{\vspace*{-7pt}
\begin{flalign}\label{alg:coeff_init}
&\hspace{-0.06in}\textbf{Initialize:}~~\b{x}^{(0)}_{(j)} = {\c{T}}_{C/2}(\b{A}^{(t)^\top}\b{y}_{(j)})& 
\end{flalign}\\[-6pt]
	\For{\[r = 0\]  \textbf{to} \[R-1\]}{\vspace{-5pt}
	\begin{flalign}\label{alg:coeff_iht}
	&\textbf{Update:}~~\b{x}^{(r+1)}_{(j)} = {\c{T}}_{\tau^{(r)}}(\b{x}^{(r)}_{(j)} - \eta_{x}^{(r)}~\b{A}^{(t)^\top}(\b{A}^{(t)}\b{x}^{(r)}_{(j)} - \b{y}_{(j)}))&
	\end{flalign}\vspace{-14pt}}}
\vspace{-1pt}

\[\hat{\b{x}}_{(j)}^{(t)}  :=\b{x}^{(R)}_{(j)} \] for \[j \in [p]\]\\
\textbf{Learn: (Update Dictionary)}\vspace{-8pt}
\begin{flalign}\label{eq:emp_grad_est}
&\hspace{0.14in}\text{Form empirical gradient estimate:}~~\hat{\b{g}}^{(t)} = \tfrac{1}{p}\textstyle\sum_{j = 1}^{p}(\b{A}^{(t)}\hat{\b{x}}_{(j)}^{(t)}   - \b{y}_{(j)}){\rm sign}(\hat{\b{x}}_{(j)}^{(t)}  )^\top&
\end{flalign}\vspace{-20pt}

\begin{flalign}\label{eq:apx_grad}
&\hspace{0.14in}\text{Take a gradient descent step:}~~\b{A}^{(t+1)} = \b{A}^{(t)} - \eta_A~\hat{\b{g}}^{(t)}&
\end{flalign}\vspace{-20pt}

\begin{flalign*}
&\hspace{0.14in}\text{Normalize:}~~\b{A}^{(t+1)}_i = \b{A}^{(t+1)}_i/\|\b{A}^{(t+1)}_i\| ~\forall~i \in [m]&
\end{flalign*}\vspace{-18pt}

}

\label{def:grad_alpha_beta}
	\textit{A vector \[\b{g}^{(t)}\] is  \[(\rho_{-}, \rho_{_+}, \zeta_t)\]-correlated with a vector \[\b{z}^*\] if 
	\vspace{-3pt}
	\begin{align*}
	\langle \b{g}^{(t)}, \b{z}^{(t)} - \b{z}^{*}\rangle \geq \rho_{-}\|\b{z}^{(t)} - \b{z}^{*}\|^2 + \rho_{+} \|\b{g}^{(t)}\|^2 - \zeta_{t}.
	\end{align*}}
	\vspace{-18pt}

\label{main_result}\textit{Suppose that assumptions \ref{assumption:mu}-\ref{assumption:step coeff}  hold, and Algorithm~\ref{alg:main_alg} is provided with  \[ p = \tilde{\Omega}(mk^2)\] new samples generated according to model \eqref{eq:model} at each iteration \[t\]. 
Then,  with probability at least \[(1 - \delta_{\text{alg}}^{(t)})\] for some small constant \[\delta_{\text{alg}}^{(t)}\], given \[R = \Omega({\rm log}(n))\], the coefficient estimate \[\hat{\b{x}}_{i}^{(t)}\] at \[t\]-th iteration has the correct signed-support and satisfies
\vspace{-2pt}
\begin{align*}
(\hat{\b{x}}_{i}^{(t)} - \b{x}_{i}^*)^2 
&= \mathcal{O}(k(1 - \omega)^{t/2}\|\b{A}_i^{(0)} - \b{A}_i^*\|), ~\text{for all}~i \in {\rm supp}({\b{x}^*}).\vspace{-2pt}


\end{align*} 
Furthermore, for some \[0 < \omega < 1/2\], the estimate \[\b{A}^{(t)}\] at \[(t)\]-th iteration satisfies 
\vspace{-2pt}
\begin{align*}
\|\b{A}_i^{(t)} - \b{A}_i^*\|^2 \leq (1 - \omega)^t\|\b{A}_i^{(0)} - \b{A}_i^*\|^2,~\text{for all}~t = 1,2,\ldots.\vspace{-2pt} .
\end{align*}
}

\label{lem:recover_sign}
	Suppose \[\b{A}^{(t)}\] is \[\epsilon_t\]-close to \[\b{A}^*\]. Then, if \[\mu = \c{O}(\log(n))\], \[k = \sqrt{n}/\mu\log(n)\], and \[\epsilon_t = \mathcal{O}^*(1/\sqrt{\log(m)})\], with probability at least \[(1 - \delta_{{\c{T}}}^{(t)})\] for each random sample \[\b{y} = \b{A}^*\b{x}^*\]:
	\begin{align*}
	{\rm sign}({\c{T}}_{C/2}((\b{A}^{(t)})^\top \b{y}) = {\rm sign}(\b{x}^*),
	\end{align*}

	where \[\delta_{{\c{T}}}^{(t)} = 2m~{\exp}({-\tfrac{C^2}{\mathcal{O}^*(\epsilon_t^2)}})\].

\label{our:signed_supp}
	Suppose \[\b{A}^{(t)}\] is \[\epsilon_t\]-close to \[\b{A}^*\],  \[\mu = \c{O}(\log(n))\], \[k = \sqrt{n}/\mu\log(n)\], and \[\epsilon_t = \mathcal{O}^*(1/\log(m))\] Then, with probability at least \[(1 - \delta_{\beta}^{(t)} - \delta_{{\c{T}}}^{(t)}  )\], each iterate of the IHT-based coefficient update step shown in \eqref{alg:coeff_iht} has the correct signed-support, if for a constant \[c^{(r)}_1(\epsilon_t, \mu, k, n) = \tilde{\Omega}({k^2}/{n})\], the step size is chosen as \[\eta_x^{(r)}\leq c^{(r)}_1\] ,






	and the threshold \[\tau^{(r)}\] is chosen as
	\begin{align*}
	\tau^{(r)} = \eta_x^{(r)}(t_\beta + \tfrac{\mu_t}{\sqrt{n}} \|\b{x}^{(r-1)} - \b{x}^*\|_1) :=c_2^{(r)}(\epsilon_t, \mu, k, n) = \tilde{\Omega}({k^2}/{n}),
	\end{align*}

	for some constants \[c_1\] and \[c_2\]. Here, \[t_\beta = \mathcal{O}(\sqrt{k\epsilon_t})\], \[\delta_{{\c{T}}}^{(t)} = 2m~{\exp}({-\tfrac{C^2}{\mathcal{O}^*(\epsilon_t^2)}})\] ,and \[\delta_{\beta}^{(t)} = 2k~{\exp}(-\tfrac{1}{\mathcal{O}(\epsilon_t)})\].

\label{iht:x_R_error}
 	With probability at least \[(1 - \delta_{\beta}^{(t)} - \delta_{{\c{T}}}^{(t)})\] the error incurred by each element \[i_1 \in {\rm supp}(\b{x}^*)\] of the coefficient estimate is upper-bounded as
 	\begin{align*}


 	|\hat{\b{x}}_{i_1} - \b{x}_{i_1}^*|

 	&\leq    \mathcal{O}(t_\beta) + \left({(R + 1)}k \eta_x\tfrac{\mu_t}{\sqrt{n}}~\underset{i}{\max}|\b{x}_{i}^{(0)} - \b{x}_{i}^*| + |\b{x}_{i_1}^{(0)} - \b{x}_{i_1}^*| \right)\delta_{R},

 	=  \mathcal{O}(t_\beta)
 	\end{align*}

 	where \[t_\beta = \mathcal{O}(\sqrt{k\epsilon_t})\], \[\delta_{R} := (1 - \eta_{x} + \eta_x\tfrac{\mu_t}{\sqrt{n}})^{R}\], \[\delta_{{\c{T}}}^{(t)} = 2m~{\exp}({-\tfrac{C^2}{\mathcal{O}^*(\epsilon_t^2)}})\], \[\delta_{\beta}^{(t)} = 2k~{\exp}(-\tfrac{1}{\mathcal{O}(\epsilon_t)})\], and \[\mu_t\] is the incoherence between the columns of \[\b{A}^{(t)}\]; see Claim~\ref{claim:incoherence of B}.

\label{iht:R_th_term}
 	With probability at least \[(1 - \delta_{\c{T}}^{(t)} - \delta_{\beta}^{(t)})\] the \[i_1\]-th element of the coefficient estimate, for each \[i_1 \in {\rm supp}(\b{x}^*)\], is given by
 	\begin{align*}
 	\hat{\b{x}}_{i_1} := \b{x}_{i_1}^{(R)} =  \b{x}_{i_1}^* (1 - \lambda^{(t)}_{i_1}) + \vartheta^{(R)}_{i_1}.
 	\end{align*}

 	Here, \[\vartheta^{(R)}_{i_1}\] is \[|\vartheta^{(R)}_{i_1}| = \mathcal{O}(t_{\beta})\], 

 	where \[t_\beta = \mathcal{O}(\sqrt{k\epsilon_t})\]. Further, \[\lambda^{(t)}_{i_1} = |\langle \b{A}^{(t)}_{i_1}- \b{A}^{*}_{i_1}, \b{A}^*_{i_1}\rangle| \leq \tfrac{\epsilon_t^2}{2}\], \[\delta_{{\c{T}}}^{(t)} = 2m~{\exp}({-\tfrac{C^2}{\mathcal{O}^*(\epsilon_t^2)}})\] and \[\delta_{\beta}^{(t)} = 2k~{\exp}(-\tfrac{1}{\mathcal{O}(\epsilon_t)})\].

\label{grad_exp}
	Suppose that \[\b{A}^{(t)}\] is \[(\epsilon_t, 2)\]-near to \[\b{A}^*\]. Then, the dictionary update step in Algorithm~\ref{alg:main_alg} amounts to the following for the \[j\]-th dictionary element
	\vspace{-5pt}
		\begin{align*}
		\b{E}[\b{A}^{(t+1)}_j] = \b{A}^{(t)}_j + \eta_A \b{g}^{(t)}_j,
		\vspace{-5pt}
		\end{align*}	
		where \[\b{g}^{(t)}_j\] is given by
			\vspace{-5pt}
		\begin{align*}
		\b{g}^{(t)}_j = q_j p_j \big((1 - \lambda^{(t)}_j)\b{A}^{(t)}_j- \b{A}^*_j + \tfrac{1}{q_j p_j}\Delta^{(t)}_j \pm \gamma\big),
		\end{align*}










	\[\lambda^{(t)}_{j}=|\langle \b{A}^{(t)}_j - \b{A}^{*}_j, \b{A}^*_j\rangle|\], and \[\Delta^{(t)}_j:=\b{E}[\b{A}^{(t)}_S\vartheta^{(R)}_S{\rm sign}(\b{x}^*_j)]\], where \[\|\Delta^{(t)}_{j}\|= \mathcal{O}(\sqrt{m}q_{i,j}p_{j}\epsilon_t\|\b{A}^{(t)}\|)\].

\label{lem:grad_vec_concentrates}
Given \[p = \tilde{\Omega}(mk^2)\] samples, the empirical gradient vector estimate corresponding to the \[i\]-th dictionary element, \[\hat{\b{g}}_i^{(t)}\] concentrates around its expectation, i.e.,
		\begin{align*}
		\|\hat{\b{g}}_i^{(t)} - \b{g}_i^{(t)}\| \leq o(\tfrac{k}{m}\epsilon_t).
		\end{align*}

		with probability at least \[(1 -\delta_{\b{g}_i}^{(t)}- \delta_{\beta}^{(t)} - \delta_{{\c{T}}}^{(t)} - \delta_{\rm HW}^{(t)})\], where \[\delta_{\b{g}_i}^{(t)} =  \exp(-\Omega(k))\].

\label{grad_corr}
Suppose \[\b{A}^{(t)}\] is \[(\epsilon_t, 2)\]-near to \[\b{A}^*\], \[k = \mathcal{O}(\sqrt{n})\] and \[\eta_A = \mathcal{O}(m/k)\]. Then, with probability at least \[(1 - \delta_{{\c{T}}}^{(t)} - \delta_{\beta}^{(t)} - \delta_{\rm HW}^{(t)} -\delta_{\b{g}_i}^{(t)})\] the empirical gradient vector \[\hat{\b{g}}^{(t)}_j\] 




	 is \[(\Omega(k/m), \Omega(m/k),0 )\]-correlated with \[(\b{A}^{(t)}_j - \b{A}^*_j)\], and for any \[t \in [T]\],
	\begin{align*}
	\|\b{A}^{(t+1)}_j- \b{A}^*_j\|^2 \leq (1 - \rho_{\_}\eta_A)\|\b{A}^{(t)}_j- \b{A}^*_j\|^2.
	\end{align*}

\label{lem:closeness}
	Suppose \[\b{A}^{(t)}\] is \[(\epsilon_t, 2)\] near to \[\b{A}^*\] with \[\epsilon_t = \mathcal{O}^*(1/\log(n))\], and number of samples used in step \[t\] is \[p = \tilde{\Omega}(mk^2)\], then with probability at least \[(1 - \delta_{{\c{T}}}^{(t)} - \delta_{\beta}^{(t)} 
	- \delta_{\rm HW}^{(t)}- \delta_{\b{g}}^{(t)})\], \[\b{A}^{(t+1)}\] satisfies \[\|\b{A}^{(t+1)} - \b{A}^*\| \leq 2\|\b{A}^*\|\].

From Lemma~\ref{grad_corr} we have that with probability at least \[(1 - \delta_{{\c{T}}}^{(t)} - \delta_{\beta}^{(t)} - \delta_{\rm HW}^{(t)} -\delta_{\b{g}_i}^{(t)})\], \[\b{g}^{(t)}_j\] is \[(\Omega(k/m), \Omega(m/k),0 )\]-correlated with \[\b{A}^*_j\]. Further, Lemma~\ref{lem:closeness} ensures that each iterate maintains the closeness property. Now, applying Lemma~\ref{arora:thm40} we have that, for \[\eta_A \leq \Theta(m/k)\], with probability at least \[(1 -\delta_{\text{alg}}^{(t)} )\] any \[t \in [T]\] satisfies
\vspace{-5pt}
\begin{align*}
\|\b{A}^{(t)}_j- \b{A}^*_j\|^2
&\leq (1 - \omega)^{t}\|\b{A}^{(0)}_j- \b{A}^*_j\|^2 \leq (1 - \omega)^{t} \epsilon_0^2.
\end{align*}

where for \[0 < \omega < 1/2\] with \[\omega = \Omega(k/m)\eta_A\]. That is, the updates converge geometrically to \[\b{A}^*\]. Further, from Lemma~\ref{iht:x_R_error}, we have that the  result on the error incurred by the coefficients. Here, \[\delta_{\text{alg}}^{(t)}  = \delta_{{\c{T}}}^{(t)} + \delta_{\beta}^{(t)} + \delta_{\rm HW}^{(t)} +\delta_{\b{g}_i}^{(t)} + \delta_{\b{g}}^{(t)})\]. That is, the updates converge geometrically to \[\b{A}^*\]. Further, from Lemma~\ref{iht:x_R_error}, we have that the error in the coefficients only depends on the error in the dictionary, which leads us to our result on the error incurred by the coefficients. This completes the proof of our main result.

