Let \[\b{y} \in \mathbb{R}^{n}\] be general sample generated as \[\b{y} = \b{A}^*\b{x}^*\], where \[\b{x}^* \in \mathbb{R}^{m}\] is a sparse random vector with support \[S = {\rm supp}(\b{x}^*)\] distributed according to \textbf{D.\ref{dist_x}}.

The initial decoding step at the \[t\]-th iteration (shown in Algorithm~\ref{alg:main_alg}) involves evaluating the inner-product between the estimate of the dictionary \[\b{A}^{(t)}\], and \[\b{y}\]. The \[i\]-th element of the resulting vector can be written as
\begin{align*}
\langle \b{A}_i^{(t)}, \b{y}\rangle &= 	
\langle \b{A}_i^{(t)}, \b{A}^*_i \rangle \b{x}^*_i + \b{w}_i,
\end{align*}

where \[\b{w}_i =  \langle \b{A}_i^{(t)}, \b{A}^*_{-i}\b{x}^*_{-i}\rangle \]. Now, since \[\|\b{A}_i^* - \b{A}^{(t)}_i\|_2 \leq \epsilon_t\] and
\begin{align*}
\|\b{A}_i^* - \b{A}^{(t)}_i\|_2^2 &= \|\b{A}_i^* \|^2 +  \|\b{A}^{(t)}_i\|^2 - 2\langle \b{A}^{(t)}_i, \b{A}^*_i \rangle = 2 - 2\langle \b{A}_i^{(t)}, \b{A}^*_i \rangle,
\end{align*}

we have
\begin{align*}
|\langle \b{A}^{(t)}_i, \b{A}^*_i \rangle| \geq 1 - \epsilon^2_t/2.
\end{align*}

Therefore, the term 
\begin{align*}
|\langle \b{A}_i^{(t)}, \b{A}^*_i\rangle \b{x}^*_i| 
\begin{cases}
	\geq (1 - \tfrac{\epsilon_t^2}{2})C &,  \text{if} ~ i \in S,\\
	= 0&,  \text{otherwise}.
\end{cases}
\end{align*}


Now, we focus on the \[\b{w}_i\] and show that it is small. 
By the definition of \[\b{w}_i\] we have
\begin{align*}
\b{w}_i = \langle \b{A}_i^{(t)}, \b{A}^*_{-i}\b{x}^*_{-i}\rangle  = \textstyle\sum\limits_{\ell\neq i}\langle \b{A}^{(t)}_i, \b{A}^*_\ell \rangle \b{x}^*_\ell = \textstyle\sum\limits_{\ell \in S\backslash \{i\}}\langle \b{A}^{(t)}_i, \b{A}^*_\ell \rangle \b{x}^*_\ell.
\end{align*}

Here, since \[var(\b{x}_\ell^*) = 1\], \[\b{w}_i\] is a zero-mean random variable with variance
\begin{align*}
var(\b{w}_i) = \textstyle\sum\limits_{\ell \in S\backslash \{i\}}\langle \b{A}^{(t)}_i, \b{A}^*_\ell \rangle^2.
\end{align*}


Now, each term in this sum can be bounded as,
\begin{align*}
\langle \b{A}_i^{(t)}, \b{A}^*_\ell \rangle^2 &= (\langle \b{A}_i^{(t)} - \b{A}_i^*, \b{A}^*_\ell\rangle + \langle \b{A}_i^*, \b{A}^*_\ell\rangle)^2\\
&\leq 2(\langle \b{A}_i^{(t)} - \b{A}_i^*, \b{A}^*_\ell\rangle^2 + \langle \b{A}_i^*, \b{A}^*_\ell\rangle^2)\\
&\leq 2(\langle \b{A}_i^{(t)} - \b{A}_i^*, \b{A}^*_\ell\rangle^2 + \tfrac{\mu^2}{n}).
\end{align*}

Next, \[\textstyle\sum\limits_{\ell\neq i} \langle \b{A}_i^{(t)} - \b{A}_i^*, \b{A}^*_\ell\rangle^2\] can be upper-bounded as	
\begin{align*}
&\textstyle\sum\limits_{\ell \in S\backslash \{i\}} \langle \b{A}_i^{(t)} - \b{A}_i^*, \b{A}^*_\ell\rangle^2 
\leq \|\b{A}_{S\backslash{\{i\}}}^{*}\|^2 \epsilon_t^2.
\end{align*}
Therefore, we have the following as per our assumptions on \[\mu\] and \[k\], 
\begin{align*}
\|\b{A}_{S\backslash{\{i\}}}^{*}\|^2 \leq  (1 + k \tfrac{\mu}{\sqrt{n}}) \leq 2,
\end{align*}

using Gershgorin Circle Theorem \citep{Gershgorin1931}. Therefore, we have
\begin{align*}
\textstyle\sum\limits_{\ell \in S\backslash \{i\}} \langle \b{A}^{(t)}_i - \b{A}_i^*, \b{A}^*_\ell\rangle^2 \leq 2\epsilon_t^2.
\end{align*}
Finally, we have that 
\begin{align*}
\textstyle\sum\limits_{\ell \in S\backslash \{i\}}\langle \b{A}_i^{(t)}, \b{A}^*_\ell \rangle^2
\leq 2( 2\epsilon^2_t + k \tfrac{\mu^2}{n}) = \mathcal{O}^*(\epsilon_t^2).
\end{align*}

Now, we apply the Chernoff bound for sub-Gaussian random variables \[\b{w}_i\] (shown in Lemma~\ref{theorem:subg_chern}) to conclude that
\begin{align*}
\mathbf{Pr}[|\b{w}_i|\geq C/4] \leq 2\exp(-\tfrac{C^2}{ \mathcal{O}^*(\epsilon_t^2)}).
\end{align*}

Further, \[\b{w}_i\] corresponding to each \[m\] should follow this bound, applying union bound we conclude that 
\begin{align*}
\mathbf{Pr}[ \underset{i}{\max}~|\b{w}_i| \geq C/4] \leq 2m\exp(-\tfrac{C^2}{\mathcal{O}^*(\epsilon_t^2)}) := \delta_{{\c{T}}}^{(t)} .
\end{align*}










	Consider the \[(r+1)\]-th iterate \[\b{x}^{(r+1)}\] for the \[t\]-th dictionary iterate, where \[\|\b{A}^{(t)}_i - \b{A}^*_i\|\leq \epsilon_t\] for all \[i \in [1, m]\] evaluated as the following by the update step described in Algorithm~\ref{alg:main_alg},
	\begin{align}
	\label{proof:update_step}
	\b{x}^{(r+1)} &= \b{x}^{(r)} - \eta_{x}^{(r+1)}\b{A}^{(t)^\top}(\b{A}^{(t)}\b{x}^{(r)} - \b{y}) \notag\\
	&= (\b{I} - \eta_{x}^{(r+1)}\b{A}^{(t)^\top}\b{A}^{(t)})\b{x}^{(r)} - \eta_{x}^{(r+1)}\b{A}^{(t)^\top}\b{A}^*\b{x}^*,
	\end{align}

	where \[\eta_{x}^{(1)} < 1\] is the learning rate or the step-size parameter. Now, using 

	 Lemma~\ref{lem:recover_sign} we know that \[\b{x}^{(0)}\] \eqref{alg:coeff_init} has the correct signed-support with probability at least \[(1-\delta_{\c{T}}^{(t)})\]. 
	Further, since \[\b{A}^{(t)^\top}\b{A}^*\] can be written as
	\begin{align*}
\b{A}^{(t)^\top}\b{A}^* = (\b{A}^{(t)}- \b{A}^{*})^{\top}\b{A}^* + \b{A}^{*\top}\b{A}^*,
	\end{align*}

	we can write the \[(r+1)\]-th iterate of the coefficient update step using \eqref{proof:update_step} as
	\begin{align*}
	\b{x}^{(r+1)}
	&= (\b{I} - \eta_{x}^{(r+1)}\b{A}^{(t)^\top}\b{A}^{(t)})\b{x}^{(r)} - \eta_{x}^{(r+1)} (\b{A}^{(t)} -\b{A}^{*})^{\top}\b{A}^*\b{x}^* + \eta_{x}^{(r+1)} \b{A}^{*\top}\b{A}^*\b{x}^*.
	\end{align*}

	Further, the \[j\]-th entry of this vector is given by
	\begin{align}
	\label{iht_eq:j_element}
	\b{x}^{(r+1)}_{j} \hspace{-3pt}= \hspace{-3pt}(\b{I} - \eta_{x}^{(r+1)} \b{A}^{(t)^\top}\hspace{-3pt}\b{A}^{(t)})_{(j,:)}\b{x}^{(r)} - \eta_{x}^{(r+1)} &((\b{A}^{(t)} - \b{A}^{*})^{\top}\hspace{-3pt}\b{A}^*)_{(j,:)}\b{x}^*  \hspace{-3pt}+\hspace{-3pt} \eta_{x}^{(r+1)}(\b{A}^{*\top}\hspace{-3pt}\b{A}^*)_{(j,:)}\b{x}^*.
	\end{align}
	We now develop an expression for the \[j\]-th element of each of the term in \eqref{iht_eq:j_element} as follows. First, we can write the first term as
	\begin{align*}
	(\b{I} - \eta_{x}^{(r+1)}\b{A}^{(t)^\top}\b{A}^{(t)})_{(j,:)}\b{x}^{(r)} & = (1 - \eta_{x}^{(r+1)}) \b{x}_j^{(r)} - \eta_{x}^{(r+1)}\textstyle\sum\limits_{i \neq j}  \langle \b{A}^{(t)}_j, \b{A}^{(t)}_i \rangle\b{x}_i^{(r)}.
	\end{align*}
	Next, the second term in \eqref{iht_eq:j_element} can be expressed as
	\begin{align*}
	\eta_{x}^{(r+1)} ((\b{A}^{(t)} - \b{A}^{*})^{\top}\b{A}^*)_{(j,:)}\b{x}^* &= \eta_{x}^{(r+1)}\textstyle\sum\limits_{i} \langle \b{A}^{(t)}_j - \b{A}^{*}_j, \b{A}^*_i\rangle \b{x}_i^*\\
	&= \eta_{x}^{(r+1)}\langle \b{A}^{(t)}_j - \b{A}^{*}_j, \b{A}^*_j\rangle \b{x}_j^* + \eta_{x}^{(r+1)}\textstyle\sum\limits_{i\neq j} \langle \b{A}^{(t)}_j - \b{A}^{*}_j, \b{A}^*_i\rangle \b{x}_i^*.
	\end{align*}
	Finally, we have the following expression for the third term,
	\begin{align*}
	\eta_{x}^{(r+1)}(\b{A}^{*\top}\b{A}^*)_{(j,:)}\b{x}^* &= \eta_{x}^{(r+1)} \b{x}_j^* + \eta_{x}^{(r+1)}\textstyle\sum\limits_{i \neq j} \langle \b{A}^*_j, \b{A}^*_i \rangle \b{x}^*_i. 

	\end{align*}
	Now using our definition of  \[\lambda^{(t)}_j = |\langle \b{A}^{(t)}_j - \b{A}^{*}_j, \b{A}^*_j\rangle| \leq \tfrac{\epsilon_t^2}{2}\], combining all the results for \eqref{iht_eq:j_element}, and using the fact that since \[\b{A}^{(t)}\] is close to \[\b{A}^*\], vectors \[\b{A}^{(t)}_j - \b{A}^{*}_j\] and \[\b{A}^*_j\] enclose an obtuse angle, we have the following for  the \[j\]-th entry of the \[(r+1)\]-th iterate, \[\b{x}^{(r+1)}\] is given by















		\begin{align}
		\label{iht_eq:r_th_iterate_xi}
		\b{x}_j^{(r+1)} =  (1 - \eta_{x}^{(r+1)}) &\b{x}_j^{(r)} + \eta_{x}^{(r+1)}(1 - \lambda^{(t)}_j) \b{x}_j^* + \eta_{x}^{(r+1)}\xi^{(r+1)}_{j} .
		\end{align}
		Here \[\xi^{(r+1)}_j\] is defined as 	 
		\begin{align*}
		\xi^{(r+1)}_{j}  &:= \textstyle\sum\limits_{i \neq j}( \langle \b{A}^{(t)}_j - \b{A}^{*}_j, \b{A}^*_i\rangle +  \langle \b{A}^{*}_j, \b{A}^*_i\rangle) \b{x}^*_i -\textstyle\sum\limits_{i \neq j} \langle \b{A}^{(t)}_j, \b{A}^{(t)}_i\rangle \b{x}_i^{(r)}.
		\end{align*}







		Since, \[\langle \b{A}^{*}_j, \b{A}^*_i\rangle  - \langle \b{A}^{(t)}_j, \b{A}^{(t)}_i\rangle = \langle \b{A}^{*}_j,  \b{A}^*_i - \b{A}^{(t)}_i\rangle  + \langle \b{A}^*_j -\b{A}^{(t)}_j, \b{A}^{(t)}_i\rangle\], we can write \[\xi^{(r+1)}_j\] as













		\begin{align}\label{eq:def_xi_r}
		\xi^{(r+1)}_{j} 

		& = \beta^{(t)}_j + \textstyle\sum\limits_{i \neq j}\langle \b{A}^{(t)}_j, \b{A}^{(t)}_i\rangle (\b{x}_i^*-\b{x}_i^{(r)}),
		\end{align}
		where \[\beta^{(t)}_j\] is defined as 
		\begin{align}\label{eq:beta_t}
		\beta^{(t)}_j
		& := \textstyle\sum\limits_{i \neq j} (\langle \b{A}^{*}_j,  \b{A}^*_i - \b{A}^{(t)}_i\rangle  + \langle \b{A}^*_j -\b{A}^{(t)}_j, \b{A}^{(t)}_i\rangle + \langle \b{A}^{(t)}_j - \b{A}^{*}_j, \b{A}^*_i\rangle) \b{x}_i^*.
		\end{align}
		Note that \[\beta^{(t)}_j\] does not change for each iteration \[r\] of the coefficient update step. Further, by Claim~\ref{lem:bound_beta} we show that \[|\beta^{(t)}_j| \leq t_\beta = \c{O}(\sqrt{k\epsilon_t})\] with probability at least \[(1-\delta_{\beta}^{(t)})\]. Next, we define \[\tilde{\xi}^{(r+1)}_{j}\] as
		\begin{align}\label{eq:xi_r_abs}
		\tilde{\xi}^{(r+1)}_{j} 
		& := \beta^{(t)}_j + \textstyle\sum\limits_{i \neq j}|\langle \b{A}^{(t)}_j, \b{A}^{(t)}_i\rangle| |\b{x}_i^{*} - \b{x}_i^{(r)}|.

		\end{align}







		where \[\xi^{(r+1)}_{j} \leq \tilde{\xi}^{(r+1)}_{j}\]. Further, using Claim~\ref{claim:incoherence of B},
		\begin{align}\label{eq:xi_til_max}
		\tilde{\xi}^{(r+1)}_{j}  &\leq t_\beta + \tfrac{\mu_t}{\sqrt{n}} \|\b{x}^*_j - \b{x}^{(r)}_j\|_1 := \tilde{\xi}^{(r+1)}_{\max} = \tilde{\mathcal{O}}(\tfrac{k}{\sqrt{n}}),
		\end{align}
		since \[\|\b{x}^{(r-1)} - \b{x}^*\|_1 =\c{O}(k)\].

		Therefore, for the \[(r+1)\]-th iteration, we choose the threshold to be 
		\begin{align}\label{eq:threshold}
		\tau^{(r+1)} := \eta_x^{(r+1)}\tilde{\xi}^{(r+1)}_{\max},
		\end{align}
		and the step-size by setting the ``noise'' component of \eqref{iht_eq:r_th_iterate_xi} to be smaller than the ``signal'' part, specifically, half the signal component, i.e., 
		\begin{align*}
		\eta_x^{(r+1)}\tilde{\xi}^{(r+1)}_{\max}  
		&\leq \tfrac{(1 - \eta_{x}^{(r+1)})}{2}\b{x}^{(r)}_{\min} + \tfrac{\eta_{x}^{(r+1)}}{2}(1-\tfrac{\epsilon_t^2}{2})C,
		\end{align*}
		 Also, since we choose the threshold as \[ \tau^{(r)} := \eta_x^{(r)}\tilde{\xi}^{(r)}_{\max}\], \[\b{x}^{(r)}_{\min} = \eta_x^{(r)}\tilde{\xi}^{(r)}_{\max}\], where \[\b{x}^{(0)}_{\min} = C/2\], we have the following for the \[(r+1)\]-th iteration,
		\begin{align*}
		\eta_x^{(r+1)}\tilde{\xi}^{(r+1)}_{\max}  
		&\leq \tfrac{(1 - \eta_{x}^{(r+1)})}{2}\eta_x^{(r)}\tilde{\xi}^{(r)}_{\max} + \tfrac{\eta_{x}^{(r+1)}}{2}(1-\tfrac{\epsilon_t^2}{2})C.
		\end{align*}
		Therefore, for this step we choose \[\eta_x^{(r+1)}\] as
		\begin{align}
		\label{iht_eq:eta_x_r}
		\eta_x^{(r+1)} \leq  \tfrac{\tfrac{\eta_x^{(r)}}{2}\tilde{\xi}^{(r)}_{\max}}{\tilde{\xi}^{(r+1)}_{\max}+ \tfrac{\eta_x^{(r)}}{2}\tilde{\xi}^{(r)}_{\max} - \tfrac{1}{2}(1-\tfrac{\epsilon_t^2}{2})C},

		\end{align}







		Therefore, 

		\[\eta_x^{(r+1)}\] can be chosen as


		\begin{align*}
		\eta_x^{(r+1)}\leq c^{(r+1)}(\epsilon_t, \mu, k, n),

		\end{align*}
		for a small constant \[c^{(r+1)}(\epsilon_t, \mu, k, n)\], \[\eta_x^{(r+1)}\]. In addition, if we set all \[\eta_x^{(r)} = \eta_x\], we have that \[\eta_x = \tilde{\Omega}(\tfrac{k}{\sqrt{n}})\] and therefore \[\tau^{(r)} = \tau =  \tilde{\Omega}(\tfrac{k^2}{n})\]. Further, since we initialize with the hard-thresholding step, the entries in \[|\b{x}^{(0)}| \geq C/2\]. Here, we define \[\tilde{\xi}^{(0)}_{\max} = C\] and \[\eta_x^{(0)} = 1/2\], and set the threshold for initial step as \[\eta_x^{(0)}\tilde{\xi}^{(0)}_{\max}\].

Using the definition of  \[\tilde{\xi}^{(\ell)}_{i_1}\] as in \eqref{eq:xi_r_abs}, we have
\begin{align*}
\tilde{\xi}^{(\ell)}_{i_1}
& = \beta^{(t)}_{i_1} +\textstyle\sum\limits_{i_2 \neq i_1}|\langle \b{A}^{(t)}_{i_1}, \b{A}^{(t)}_{i_2}\rangle| | \b{x}_{i_2}^* - \b{x}_{i_2}^{(\ell-1)}|.
\end{align*}

From Claim~\ref{lem:bound_beta}  we have that \[|\beta^{(t)}_{i_1}| \leq t_\beta\] with probability at least \[(1-\delta_{\beta}^{(t)})\]. Further, using Claim~\ref{claim:incoherence of B} , and letting \[C_{i}^{(\ell)} := |\b{x}_{i}^* - \b{x}_{i}^{(\ell)}| = |\b{x}_{i}^{(\ell)} - \b{x}_{i}^*|\], 

 \[\tilde{\xi}^{(\ell)}_{i_1}\] can be upper-bounded as
\begin{align}\label{eq:xi_l_ub}
\tilde{\xi}^{(\ell)}_{i_1}
& \leq \beta^{(t)}_{i_1} + \tfrac{\mu_t}{\sqrt{n}}\textstyle\sum\limits_{i_2 \neq i_1} C_{i_2}^{(\ell-1)}.
\end{align}

Rearranging the expression for \[(r+1)\]-th update \eqref{iht_eq:r_th_iterate_xi}, and using \eqref{eq:xi_l_ub} we have the following upper-bound












\begin{align*}
C_{i_1}^{(r+1)} \leq  (1 - \eta_{x}^{(r+1)}) C_{i_1}^{(r)} + \eta_{x}^{(r+1)}\lambda_{i_1}^{(t)} |\b{x}_{i_1}^*|  + \eta_{x}^{(r+1)} \tilde{\xi}^{(r+1)}_{i_1}.
\end{align*}
Next, recursively substituting in for \[C_{i_1}^{(r)}\], where we define \[\textstyle\prod_{q = \ell}^{\ell} (1-\eta_x^{(q+1)})= 1\],
\begin{align*}
C_{i_1}^{(r+1)} \hspace{-3pt}\leq C_{i_1}^{(0)} \textstyle\prod\limits_{q = 0}^{r}\hspace{-3pt}(1 - \eta_x^{(q+1)})  + \lambda_{i_1}^{(t)} |\b{x}_{i_1}^*| \sum\limits_{\ell=1}^{r+1}\eta_x^{(\ell)}\prod\limits_{q = \ell}^{r+1} (1-\eta_x^{(q+1)})   + \sum\limits_{\ell=1}^{r+1} \eta_x^{(\ell)}\tilde{\xi}_{i_1}^{(\ell)}\prod\limits_{q = \ell}^{r+1} (1-\eta_x^{(q+1)}) .
\end{align*}

Substituting for the upper-bound of \[\tilde{\xi}_{i_1}^{(\ell)}\] from \eqref{eq:xi_l_ub},








\begin{align}
\label{iht:def_C_j_rplus1}
C_{i_1}^{(r+1)} 
&\leq  \alpha^{(r+1)}_{i_1}  + \tfrac{\mu_t}{\sqrt{n}}\textstyle\sum\limits_{\ell=1}^{r+1} \eta_x^{(\ell)}\sum\limits_{i_2 \neq i_1} C_{i_2}^{(\ell-1)}\prod\limits_{q = \ell}^{r+1} (1-\eta_x^{(q+1)}).
\end{align}
Here, \[\alpha^{(r+1)}_{i_1}\] is defined as
\begin{align}
\label{iht:def_alpha_j_rplus1}
\alpha^{(r+1)}_{i_1} = C_{i_1}^{(0)} \textstyle\prod\limits_{q = 0}^{r}(1 - \eta_x^{(q+1)})  + (\lambda_{i_1}^{(t)} |\b{x}_{i_1}^*| +\beta^{(t)}_{i_1}) \sum\limits_{\ell=1}^{r+1}\eta_x^{(\ell)}\prod\limits_{q = \ell}^{r+1} (1-\eta_x^{(q+1)}).
\end{align}









Our aim now will be to express \[C_{i_1}^{(\ell)}\] for \[\ell>0\] in terms of \[C_{i_2}^{(0)}\]. Let each \[\alpha^{(\ell)}_{j} \leq \alpha^{(\ell)}_{i}\] where \[ j = i_1, i_2, \dots, i_k\]. Similarly, let \[C_{j}^{(0)} \leq C_i^{(0)}\] for \[j = i_1, i_2, \dots, i_k\], and all \[\eta_x^{(\ell)} = \eta_x\]. Then, using Claim~\ref{iht:gen_term_simple} we have the following expression for \[C_{i_1}^{({R}+1)}\], 
\begin{align*}
C_{i_1}^{({R}+1)} 
\leq \alpha^{({R}+1)}_{i_1} + (k-1)\eta_x\tfrac{\mu_t}{\sqrt{n}} \textstyle\sum\limits_{\ell = 1}^{{R}}  \alpha^{(\ell)}_{\max}\big(1-\eta_x + &\eta_x\tfrac{\mu_t}{\sqrt{n}} \big)^{{R} -\ell}
\\&+ (k-1)\eta_x\tfrac{\mu_t}{\sqrt{n}}C_{\max}^{(0)} \big(1-\eta_x + \eta_x\tfrac{\mu_t}{\sqrt{n}} \big)^{R}. 
\end{align*}
Here,  \[(1 - \eta_{x})^{R} \leq (1 - \eta_{x} + \eta_x\tfrac{\mu_t}{\sqrt{n}})^{R} \leq \delta_{R}\]. Next from Claim~\ref{iht:C_i1_inter_alpha_sum} we have that with probability at least \[(1 - \delta_{\beta}^{(t)})\],
\begin{align*}
\textstyle\sum\limits_{\ell = 1}^{{R}}  \alpha^{(\ell)}_{\max}\big(1-\eta_x + \eta_x\tfrac{\mu_t}{\sqrt{n}} \big)^{{R} -\ell} 
