	\b{W}_j = \tfrac{1}{p} (\b{y}_{(j)}-\b{A}^{(t)}\hat{\b{x}}_{(j)}) {\rm sign}(\hat{\b{x}}_{(j)})^\top- \tfrac{1}{p} \mathbf{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}){\rm sign}(\hat{\b{x}})^\top].
	\end{align*}

	Noting that \[\mathbf{E}[\b{W}_j] = 0\], we will employ the matrix Bernstein result (Lemma~\ref{matrix_bernstein}) to bound \[\|\hat{\b{g}}^{(t)} - \b{g}^{(t)}\|\]. To this end, we will bound \[\|\b{W}_j\|\] and the variance proxy
	\begin{align*}
	v(\b{W}_j) = \max \{\|\textstyle\sum_{j=1}^{p} \mathbf{E}[\b{W}_j\b{W}_j^\top]\|, \|\textstyle\sum_{j=1}^{p} \mathbf{E}[\b{W}_j^\top \b{W}_j]\| \}.
	\end{align*}


	\noindent\textbf{Bound on \[\|\b{W}_j\|\]}-- First, we can bound both terms in the expression for \[\b{W}_j\]  by triangle inequality as
	\begin{align*}
	\|\b{W}_j\| 

	&\leq \tfrac{1}{p} \|(\b{y}_{(j)}-\b{A}^{(t)}\hat{\b{x}}_{(j)}) {\rm sign}(\hat{\b{x}}_{(j)})^\top\| + \tfrac{1}{p} \|\mathbf{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}){\rm sign}(\hat{\b{x}})^\top\|,\\
	& \leq \tfrac{2}{p}\|(\b{y}-\b{A}^{(t)}\hat{\b{x}}){\rm sign}(\hat{\b{x}})^\top\|.
	\end{align*}

	Here, we use Jensen's inequality for the second term, followed by upper-bounding the expected value of the argument by \[\|(\b{y}-\b{A}^{(t)}\hat{\b{x}}) {\rm sign}(\hat{\b{x}})^\top\|\].

	Next, using Claim~\ref{norm_bound_y_Ax_s} we have that with probability at least \[(1 - \delta_{\beta}^{(t)} - \delta_{{\c{T}}}^{(t)} - \delta_{\rm HW}^{(t)})\],  \[\|\b{y}-\b{A}^{(t)}\hat{\b{x}}\|\] is 
	\[\siri{\tilde{\mathcal{O}}(kt_{\beta})}\], and the fact that \[\| {\rm sign}(x)^T\| = \sqrt{k}\],
	\begin{align*}
	\|\b{W}_j\| &\leq \tfrac{2}{p}\sqrt{k}\|(\b{y}-\b{A}^{(t)}\hat{\b{x}})\|  = 

	 \siri{\mathcal{O}(\tfrac{k\sqrt{k}}{p}t_{\beta})}.
	\end{align*}

	\noindent\textbf{Bound on  the variance statistic \[v(\b{W}_j)\]}-- For the variance statistic, we first look at \[\|\textstyle\sum \mathbf{E}[\b{W}_j\b{W}_j^\top]\|\], 
	\begin{align*}
	\mathbf{E}[\b{W}_j\b{W}_j^\top] = 



	\tfrac{1}{p^2}  \mathbf{E}[(\b{y}_{(j)}-\b{A}^{(t)}&\hat{\b{x}}_{(j)}){\rm sign}(\hat{\b{x}}_{(j)})^\top  - \mathbf{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}) {\rm sign}(\hat{\b{x}})^\top]\\
	&\times [{\rm sign}(\hat{\b{x}}_{(j)}) (\b{y}_{(j)}-\b{A}^{(t)}\hat{\b{x}}_{(j)}) ^\top -(\mathbf{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}) {\rm sign}(\hat{\b{x}})^\top)^\top].
	\end{align*}
	Since \[\b{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}) {\rm sign}(\hat{\b{x}})^\top]\b{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}) {\rm sign}(\hat{\b{x}})^\top]^\top\] is positive semidefinite, 
	\begin{align*}
	\mathbf{E}[\b{W}_j\b{W}_j^\top] \preceq \tfrac{1}{p^2}  \mathbf{E}[(\b{y}_{(j)}-\b{A}^{(t)}\hat{\b{x}}_{(j)}) {\rm sign}(\hat{\b{x}}_{(j)})^\top {\rm sign}(\hat{\b{x}}_{(j)}) (\b{y}_{(j)}-\b{A}^{(t)}\hat{\b{x}}_{(j)})^\top].
	\end{align*}

	Now, since each \[\hat{\b{x}}_{(j)}\] has \[k\] non-zeros, \[{\rm sign}(\hat{\b{x}}_{(j)})^\top{\rm sign}(\hat{\b{x}}_{(j)}) = k\], and using Claim~\ref{norm_exp_yAs_yAst}, with probability at least \[(1-\delta_{{\c{T}}}^{(t)} - \delta_{\beta}^{(t)})\]
	\begin{align*}
	\|\textstyle\sum \mathbf{E}[\b{W}_j\b{W}_j^\top]\|
	&\leq  \tfrac{k}{p } \|\mathbf{E}[(\b{y}_{(j)}-\b{A}^{(t)}\hat{\b{x}}_{(j)}) (\b{y}_{(j)}-\b{A}^{(t)}\hat{\b{x}}_{(j)})^\top]\|, \\ 


	&=\mathcal{O}(\tfrac{k^3t_{\beta}^2}{pm})\|\b{A}^*\|^2.
	\end{align*}

	Similarly, expanding \[\mathbf{E}[\b{W}_j^\top\b{W}_j] \], and using the fact that \[\mathbf{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}) {\rm sign}(\hat{\b{x}})^\top]^\top\mathbf{E}[(\b{y}-\b{A}^{(t)}\hat{\b{x}}) {\rm sign}(\hat{\b{x}})^\top]\] is positive semi-definite.  Now, using Claim~\ref{norm_bound_y_Ax_s} and the fact that entries of \[\mathbf{E}[({\rm sign}(\hat{\b{x}}_{(j)}) {\rm sign}(\hat{\b{x}}_{(j)})^\top]\] are \[q_i\] on the diagonal and zero elsewhere, where \[q_i = \mathcal{O}(k/m)\], 
	\begin{align*}
	\|\textstyle\sum \mathbf{E}[\b{W}_j^\top\b{W}_j]\| 
	&\preceq\tfrac{1}{p}\|\mathbf{E}[({\rm sign}(\hat{\b{x}}_{(j)})(\b{y}_{(j)}-\b{A}^{(t)}\hat{\b{x}}_{(j)})^\top (\b{y}_{(j)}-\b{A}^{(t)}\hat{\b{x}}_{(j)}) {\rm sign}(x^{(R)}_{(j)})^\top]\|,\\
	&\leq \tfrac{1}{p}\|\mathbf{E}[({\rm sign}(\hat{\b{x}}_{(j)}) {\rm sign}(\hat{\b{x}}_{(j)})^\top] \| \|\b{y}_{(j)}-\b{A}^{(t)}\hat{\b{x}}_{(j)}\|^2,\\


    &\leq  \siri{\mathcal{O}(\tfrac{k}{mp}) \tilde{\mathcal{O}}(k^2t_{\beta}^2)} = \siri{\tilde{\mathcal{O}}(\tfrac{k^3t_{\beta}^2}{mp}) }.
	\end{align*}





	Now, we are ready to apply the matrix Bernstein result. Since, \[m = O(n)\] the variance statistic comes out to be \[\mathcal{O}(\tfrac{k^3t_{\beta}^2}{pm})\|\b{A}^*\|^2\], then as long as we choose \[p = \tilde{\Omega}(mk^2)\] (using the bound on \[t_\beta\]), with probability at least \[(1 - \delta_{\beta}^{(t)} - \delta_{{\c{T}}}^{(t)} - \delta_{\rm HW}^{(t)} - \delta_\b{g}^{(t)})\]
	\begin{align*}
	\|\hat{\b{g}}^{(t)} -  \b{g}^{(t)}\| &\leq 	\mathcal{O}(\tfrac{k\sqrt{k}}{p}t_{\beta}) + 
\|\b{A}^*\|\sqrt{\mathcal{O}(\tfrac{k^3t_{\beta}^2}{pm})},\\ 
	&= \mathcal{O}^*(\tfrac{k}{m}  \|\b{A}^*\| ).
	\end{align*}

	where \[\delta_{\b{g}}^{(t)} = (n+m)\exp(-\Omega(m\sqrt{\log(n)})\].

This lemma ensures that the dictionary iterates maintain the closeness property (Def.\ref{def:del_kappa}) and satisfies the prerequisites for Lemma~\ref{grad_corr}. 

The update step for the \[i\]-th dictionary element at the \[s+1\] iteration can be written as
\begin{align*}
\b{A}_i^{(t+1)} - \b{A} _i^* &= \b{A}_i^{(t)} - \b{A}_i^* - \eta_A \hat{\b{g}}_i^{(t)},\\
&=  \b{A}_i^{(t)} - \b{A}_i^*  - \eta_A \b{g}_i^{(t)} - \eta_A (\hat{\b{g}}_i^{(t)} - \b{g}_i^{(t)}).
\end{align*}

Here, \[\b{g}_i^{(t)}\] is given by the following as per Lemma~\ref{grad_exp} with probability at least \[(1 - \delta_{{\c{T}}}^{(t)} - \delta_{\beta}^{(t)})\]
\begin{align*}
\b{g}^{(t)}_i
&= q_i p_i (\b{A}^{(t)}_i- \b{A}^*_i)  + q_i p_i(- \lambda^{(t)}_i\b{A}^{(t)}_i+ \tfrac{1}{q_i p_i}\Delta^{(t)}_i \pm \gamma).
\end{align*}

Substituting the expression for \[\b{g}_i^{(t)}\] in the dictionary update step,
\begin{align*}
\b{A}_i^{(t+1)} - \b{A} _i^* &= (1 - \eta_A p_i q_i) (\b{A}_i^{(t)} - \b{A}_i^*)  - \eta_A p_i q_i\lambda^{(t)}_i \b{A}^{(t)}_i 
- \eta_A \Delta^{(t)}_i   - \eta_A (\hat{\b{g}}_i^{(t)} -  \b{g}_i^{(t)}) \pm \gamma,
\end{align*}

where \[\Delta^{(t)}_j= \b{E}[\b{A}^{(t)}\vartheta^{(R)}{\rm sign}(\b{x}^*_j)] _j\].






















Therefore, the update step for the dictionary (matrix) can be written as
\begin{align}\label{eq:closeness}
\b{A}^{(t+1)} - \b{A}^* 
&=  (\b{A}^{(t)} - \b{A}^*)\diag({(1 - \eta_A p_i q_i)})  + \eta_A \b{U}  - \eta_A \b{V} \pm \gamma - \eta_A (\hat{\b{g}}^{(t)} -  \b{g}^{(t)}),
\end{align}

where, \[\b{U} =  \b{A}^{(t)} \diag({p_i q_i\lambda^{(t)}_i}) \] and \[\b{V}  = \b{A}^{(t)} \b{Q}\], with the matrix \[\b{Q}\] given by,
\begin{align*}
\b{Q}_{i,j} = q_{i,j}\b{E}_{\b{x}_S^*}[\vartheta^{(R)}_i{\rm sign}(\b{x}^*_{j})|S],




\end{align*}

and using  the following intermediate result shown in Claim~\ref{iht:bound_vareps},


















	\begin{align*}
	\b{E}_{\b{x}_S^*}[\vartheta^{(R)}_{i}{\rm sign}(\b{x}^*_{j})|S] 
	\begin{cases}
	\leq  \gamma^{(R)}_i, & ~\text{for}~ i = j, \\
	 = \mathcal{O}(p_{j}\epsilon_t ),& ~\text{for}~ i \neq j,
	\end{cases}
	\end{align*}

  we have \[\|\b{Q}_i\| = \mathcal{O}(\sqrt{m}q_{i,j}p_{i}\epsilon_t)\]. Hence, we have






\begin{align*}
\|\b{Q}\|_F \leq   \mathcal{O}(mq_{i,j}p_{i}\epsilon_t).

\end{align*}

Therefore,
\begin{align*}
\|\b{V}\| \leq \|\b{A}^{(t)} \b{Q}\| \leq 	\|\b{A}^{(t)}\| \|\b{Q}\|_F = \mathcal{O}(mq_{i,j}p_{i}\epsilon_t \|\b{A}^*\|) = \mathcal{O}(\tfrac{k^2}{m \log(n)}) \|\b{A}^*\|. 
\end{align*}






We will now proceed to bound each term in \eqref{eq:closeness}. Starting with \[(\b{A}^{(t)} - \b{A}^*)\diag{(1 - \eta_A p_i q_i)}\], and using the fact that \[p_i = O(1)\], \[q_i = O(k/m)\], and \[\|\b{A}^{(t)} - \b{A}^*\| \leq 2\|\b{A}^*\|\], we have
\begin{align*}
\|(\b{A}^{(t)} - \b{A}^*)\diag{(1 - \eta_A p_i q_i)}\| &\leq (1 - \underset{i}{\min}~\eta_A p_i q_i)\|(\b{A}^{(t)} - \b{A}^*)\| 
\leq 2(1 -  \Omega(\eta_A k/m))\|\b{A}^*\|.
\end{align*}

Next, since \[\|\b{A}^{(t)}_j\| = 1\], we have \[\lambda^{(t)}_{j} = |\langle \b{A}^{(t)}_j - \b{A}^{*}_j, \b{A}^*_j\rangle| = \tfrac{1}{2}\| \b{A}^{(t)}_j - \b{A}^{*}_j\|^2\], and \[\lambda^{(t)}_i \leq \epsilon^2_t/2\], therefore
\begin{align*}
\|\b{U}\| &= \|\b{A}^{(t)} \diag({p_i q_i\lambda^{(t)}_i}) \| \leq \underset{i}{\max}~p_i q_i\tfrac{\epsilon_t^2}{2}\|\b{A}^{(t)} - \b{A}^* + \b{A}^*\| \leq o(k/m) \| \b{A}^*\|.
\end{align*}

Using the results derived above, and the the result derived in Lemma~\ref{lem:grad_mat} which states that with probability at least \[(1 - \delta_{\beta}^{(t)} - \delta_{{\c{T}}}^{(t)} - \delta_{\rm HW}^{(t)} - \delta_\b{g}^{(t)})\], \[\|\hat{\b{g}}^{(t)} - \b{g}^{(t)}\| = \mathcal{O}^*(\tfrac{k}{m}  \|\b{A}^*\| ) )\] we have
\begin{align*}
\|\b{A}^{(t+1)} - &\b{A}^*\|= \|(\b{A}^{(t)} - \b{A}^*)\b{D}_{(1 - \eta_A p_i q_i)}\|  + \eta_A \|\b{U}\|  + \eta_A \|\b{V}\|  + \eta_A \|(\hat{\b{g}}^{(t)} -  \b{g}^{(t)})\| \pm \gamma,\\
&\leq 2(1 -  \Omega(\eta_A \tfrac{k}{m}) \|\b{A}^*\|+    o(\eta_A \tfrac{k}{m})\|\b{A}^*\| +   \mathcal{O}( \eta_A \tfrac{k^2}{m\log(n)})\|\b{A}^*\|  + o(\eta_{A}\tfrac{k}{ m} \|\b{A}^*\| ) \pm \gamma,\\

&\leq 2\|\b{A}^*\|.
\end{align*}

We start by looking at the incoherence between the columns of \[\b{A}^*\], for \[j \neq i\],
\begin{align*}
\langle \b{A}^*_i, \b{A}^*_j \rangle &= \langle \b{A}^*_i - \b{A}^{(t)}_i, \b{A}^*_j \rangle + \langle \b{A}^{(t)}_i, \b{A}^*_j  \rangle,\\
&= \langle \b{A}^*_i - \b{A}^{(t)}_i, \b{A}^*_j \rangle + \langle \b{A}^{(t)}_i,  \b{A}^*_j -  \b{A}^{(t)}_j \rangle +  \langle  \b{A}^{(t)}_i ,  \b{A}^{(t)}_j \rangle.
\end{align*}

Since \[\langle \b{A}^*_i, \b{A}^*_j \rangle \leq \tfrac{\mu}{\sqrt{n}}\], 
\begin{align*}
|\langle \b{A}^{(t)}_i, \b{A}^{(t)}_j\rangle| &\leq \langle \b{A}^*_i, \b{A}^*_j \rangle - \langle \b{A}^*_i - \b{A}^{(t)}_i, \b{A}^*_j \rangle - \langle \b{A}^{(t)}_i, \b{A}^*_j - \b{A}^{(t)}_j\rangle,\\
&\leq \tfrac{\mu}{\sqrt{n}} + 2\epsilon_t.
\end{align*}

\label{lem:bound_beta}
\begin{em}
	With probability \[(1-\delta_{\beta}^{(t)})\], \[|\beta^{(t)}_j|\] is upper-bounded by \[t_\beta = \mathcal{O}(\sqrt{k\epsilon_t})\], where \[\delta_{\beta}^{(t)} = 2k~{\exp}(-\tfrac{1}{\mathcal{O}(\epsilon_t)})\].
\end{em}

We have the following definition for \[\beta^{(t)}_j\] from \eqref{eq:beta_t},
\begin{align*}
\beta^{(t)}_j
& = \textstyle\sum\limits_{i \neq j} (\langle \b{A}^{*}_j,  \b{A}^*_i - \b{A}^{(t)}_i\rangle  + \langle \b{A}^*_j -\b{A}^{(t)}_j, \b{A}^{(t)}_i\rangle + \langle \b{A}^{(t)}_j - \b{A}^{*}_j, \b{A}^*_i\rangle) \b{x}_i^*.
\end{align*}
Here, since \[\b{x}_i^*\] are independent sub-Gaussian random variables, \[\beta^{(t)}_j\] is a sub-Gaussian random variable with the variance parameter evaluated as shown below
\begin{align*}
var[\beta^{(t)}_j] =  \textstyle\sum_{i \neq j} (\langle \b{A}^{*}_j,  \b{A}^{(t)}_i - \b{A}^*_i\rangle  + \langle \b{A}^{(t)}_j -\b{A}^*_j, \b{A}^{(t)}_i\rangle + \langle \b{A}^{(t)}_j - \b{A}^{*}_j, \b{A}^*_i\rangle)^2 \leq 9k\epsilon_t^2.
\end{align*}

Therefore, by Lemma~\ref{theorem:subg_chern} 
\begin{align*}
\b{Pr}[|\beta^{(t)}_j|>t_{\beta}] 

&\leq 2{\rm exp}(-\tfrac{t_{\beta}^2}{18k\epsilon_t^2}).
\end{align*}

Now, we need this for each \[\beta^{(t)}_j\] for \[j \in {\rm supp}(\b{x}^*)\],  union bounding over \[k\] coefficients
\begin{align*}
\b{Pr}[\max|\beta^{(t)}_j|>t_{\beta}] 
&\leq \delta_{\beta}^{(t)},
\end{align*}

where \[\delta_{\beta}^{(t)} = 2k~{\exp}(-\tfrac{t_{\beta}^2}{18k\epsilon_t^2})\]. Choosing \[t_\beta = \mathcal{O}(\sqrt{k\epsilon_t})\], we have that \[\delta_{\beta}^{(t)} = 2k~{\exp}(-\tfrac{1}{\mathcal{O}(\epsilon_t)})\].

\label{iht:gen_term_simple}
\begin{em}
The error in a general iterate \[r\]  of the coefficient estimation is upper-bounded as
	\begin{align*}
	C_{i_1}^{(r+1)} 
	&\leq \alpha^{(r+1)}_{i_1} + (k-1)\eta_x\tfrac{\mu_t}{\sqrt{n}} \textstyle\sum\limits_{\ell = 1}^{r}  \alpha^{(\ell)}_{\max}\big(1-\eta_x + \eta_x\tfrac{\mu_t}{\sqrt{n}} \big)^{r -\ell}
	\\&\hspace{7cm}+ (k-1)\eta_x\tfrac{\mu_t}{\sqrt{n}}C_{\max}^{(0)} \big(1-\eta_x + \eta_x\tfrac{\mu_t}{\sqrt{n}} \big)^r.
	\end{align*}

	\end{em}

From \eqref{iht:def_C_j_rplus1} we have the following expression for \[C_{i_1}^{(r+1)}\]
\begin{align*}
C_{i_1}^{(r+1)} 
&\leq  \alpha^{(r+1)}_{i_1}  + \tfrac{\mu_t}{\sqrt{n}}\textstyle\sum\limits_{\ell=1}^{r+1} \eta_x^{(\ell)}\sum\limits_{i_2 \neq i_1} C_{i_2}^{(\ell-1)}\prod\limits_{q = \ell}^{r+1} (1-\eta_x^{(q+1)}).
\end{align*}

Our aim will be to recursively substitute for \[C_{i_1}^{(\ell-1)} \] to develop an expression for \[C_{i_1}^{(r+1)}\] as a function of \[C_{\max}^{0}\]. To this end, we start by analyzing the iterates \[C_{i_1}^{(1)}\], \[C_{i_1}^{(2)}\], and so on to develop an expression for \[C_{i_1}^{(r+1)}\] as follows. 

\noindent\textbf{Expression for \[C_{i_1}^{(1)}\]} -- Consider \[C_{i_1}^{(1)}\]
\begin{align}\label{eq:C_i_1}
C_{i_1}^{(1)} 
&\leq \textstyle \alpha^{(1)}_{i_1}  + \tfrac{\mu_t}{\sqrt{n}}\sum\limits_{\ell=1}^{1} \eta_x\sum\limits_{i_2 \neq i_1} C_{i_2}^{(\ell-1)}\prod\limits_{q = \ell}^{1} (1-\eta_x),\notag \\
&=  \textstyle\alpha^{(1)}_{i_1}  +  \eta_x\big(\tfrac{\mu_t}{\sqrt{n}}\sum\limits_{i_1 \neq i_2} C_{i_2}^{(0)}\big).
\end{align}


\noindent\textbf{Expression for \[C_{i_1}^{(2)}\]}-- Next, \[C_{i_1}^{(2)}\] is given by
\begin{align*}
C_{i_1}^{(2)} 
&\leq  \alpha^{(2)}_{i_1}  + \eta_x\tfrac{\mu_t}{\sqrt{n}}\textstyle\sum\limits_{\ell=1}^{2}\sum\limits_{i_2 \neq i_1} C_{i_2}^{(\ell-1)} \prod\limits_{q = \ell}^{2} (1-\eta_x),\\
&\leq\textstyle \alpha^{(2)}_{i_1}  + \eta_x\tfrac{\mu_t}{\sqrt{n}}\big(\sum\limits_{i_2 \neq i_1} C_{i_2}^{(1)} + \sum\limits_{i_2 \neq i_1} C_{i_2}^{(0)}(1-\eta_x)  \big).
\end{align*}

Further, we know from \eqref{eq:C_i_1} we have
\begin{align*}
C_{i_2}^{(1)} 

&=  \alpha^{(1)}_{i_2}  +  \eta_x\tfrac{\mu_t}{\sqrt{n}}\textstyle\sum\limits_{i_3 \neq i_2} C_{i_3}^{(0)}.
\end{align*}

Therefore, since \[\sum\limits_{i_2 \neq i_1}\sum\limits_{i_3 \neq i_2} = \sum\limits_{i_3 \neq i_2, i_1}\],
\begin{align}\label{eq:C_i_2}
C_{i_1}^{(2)} 
&\leq\textstyle \alpha^{(2)}_{i_1}  + \eta_x\tfrac{\mu_t}{\sqrt{n}}\big(\sum\limits_{i_2 \neq i_1} \big(\alpha^{(1)}_{i_2}  +  \eta_x\tfrac{\mu_t}{\sqrt{n}}\textstyle\sum\limits_{i_3 \neq i_2} C_{i_3}^{(0)}\big)+ \textstyle\sum\limits_{i_2 \neq i_1} C_{i_2}^{(0)}(1-\eta_x)\big),\notag\\
&= \alpha^{(2)}_{i_1}  + \eta_x\tfrac{\mu_t}{\sqrt{n}}\textstyle\sum\limits_{i_2 \neq i_1} \alpha^{(1)}_{i_2}  +  \eta_x\tfrac{\mu_t}{\sqrt{n}}\big(\eta_x\tfrac{\mu_t}{\sqrt{n}}\textstyle\sum\limits_{i_3 \neq i_2, i_1} C_{i_3}^{(0)}+ \textstyle\sum\limits_{i_2 \neq i_1} C_{i_2}^{(0)}(1-\eta_x)\big).
\end{align}



















\noindent\textbf{Expression for \[C_{i_1}^{(3)}\]}-- Next, we writing \[C_{i_1}^{(3)}\],
\begin{align*}
C_{i_1}^{(3)} 


&\leq \alpha^{(3)}_{i_1}  + \eta_x\tfrac{\mu_t}{\sqrt{n}}\textstyle\sum_{\ell=1}^{3}\textstyle\sum\limits_{i_2 \neq i_1} C_{i_2}^{(\ell -1)}(1-\eta_x)^{3 - \ell},\\
&= \alpha^{(3)}_{i_1}  + \eta_x\tfrac{\mu_t}{\sqrt{n}} \textstyle\sum\limits_{i_2 \neq i_1}\big(  C_{i_2}^{(0)}(1-\eta_x)^{2} + C_{i_2}^{(1)}(1-\eta_x) +  C_{i_2}^{(2)}\big),\\
&\leq \alpha^{(3)}_{i_1}  + \eta_x\tfrac{\mu_t}{\sqrt{n}} \textstyle\sum\limits_{i_2 \neq i_1}\big(  C_{i_2}^{(0)}(1-\eta_x)^{2} + \big(\alpha^{(1)}_{i_2}  +  \eta_x\tfrac{\mu_t}{\sqrt{n}}\textstyle\sum\limits_{i_3 \neq i_2} C_{i_3}^{(0)}\big)(1-\eta_x) +  C_{i_2}^{(2)}\big).
\end{align*}

Here, using \eqref{eq:C_i_2} we have the following expression for \[C_{i_2}^{(2)}\]
\begin{align*}
C_{i_2}^{(2)} 
&\leq \alpha^{(2)}_{i_2}  + \eta_x\tfrac{\mu_t}{\sqrt{n}}\textstyle\sum\limits_{i_3 \neq i_2} \alpha^{(1)}_{i_3}  +  \eta_x\tfrac{\mu_t}{\sqrt{n}}\big(\eta_x\tfrac{\mu_t}{\sqrt{n}}\textstyle\sum\limits_{i_4 \neq i_3, i_2} C_{i_4}^{(0)}+ \textstyle\sum\limits_{i_3 \neq i_2} C_{i_3}^{(0)}(1-\eta_x)\big).
\end{align*}

Substituting for \[C_{i_2}^{(2)}\] in the expression for \[C_{i_1}^{(3)}\],










and rearranging the terms in the expression for \[C_{i_1}^{(3)} \], we have
\begin{align}\label{eq:C_i_3}
C_{i_1}^{(3)} 
&\leq \alpha^{(3)}_{i_1} + \eta_x\tfrac{\mu_t}{\sqrt{n}} \textstyle\sum\limits_{i_2 \neq i_1}\alpha^{(2)}_{i_2} +\eta_x\tfrac{\mu_t}{\sqrt{n}}\big( (1-\eta_x) \textstyle\sum\limits_{i_2 \neq i_1}\alpha^{(1)}_{i_2} + \eta_x\tfrac{\mu_t}{\sqrt{n}} \textstyle\sum\limits_{i_3 \neq i_2, i_1} \alpha^{(1)}_{i_3}\big) \notag \\
&
+  \eta_x\tfrac{\mu_t}{\sqrt{n}}\big((1-\eta_x)^{2} \textstyle\sum\limits_{i_2 \neq i_1}C_{i_2}^{(0)} +  2(1-\eta_x)(\eta_x\tfrac{\mu_t}{\sqrt{n}})\textstyle\sum\limits_{i_3 \neq i_2, i_1} C_{i_3}^{(0)} +  (\eta_x\tfrac{\mu_t}{\sqrt{n}})^2\textstyle\sum\limits_{i_4 \neq i_3, i_2, i_1} C_{i_4}^{(0)}\big).
\end{align}

\noindent\textbf{Expression for \[C_{i_1}^{(4)}\]}--	Now, consider \[C_{i_1}^{(4)}\]
\begin{align*}
&C_{i_1}^{(4)} 
\leq \alpha^{(4)}_{i_1}  + \eta_x\tfrac{\mu_t}{\sqrt{n}}\textstyle\sum_{\ell=1}^{4}\textstyle\sum_{i_2 \neq i_1} C_{i_2}^{(\ell -1)}(1-\eta_x)^{4 - \ell},\\

&\leq \alpha^{(4)}_{i_1}  + \eta_x\tfrac{\mu_t}{\sqrt{n}}\big(\textstyle\sum_{i_2 \neq i_1} C_{i_2}^{(0)}(1-\eta_x)^{3} + \textstyle\sum_{i_2 \neq i_1} C_{i_2}^{(1)}(1-\eta_x)^{2} + \textstyle\sum_{i_2 \neq i_1} C_{i_2}^{(2)}(1-\eta_x)^{1} \\&\hspace{10cm}+ \textstyle\sum_{i_2 \neq i_1} C_{i_2}^{(3)}(1-\eta_x)^{0}\big).
\end{align*}











































Substituting for \[C_{i_2}^{(3)}\] from \eqref{eq:C_i_3}, \[C_{i_2}^{(2)}\] from \eqref{eq:C_i_2}, \[C_{i_2}^{(1)}\] using \eqref{eq:C_i_1}, and rearranging,
\begin{align*}
&C_{i_1}^{(4)} 
